import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00
_STR_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def _to_cents(value):
    """Validate value and return exact positive integer cents (no context use)."""
    if isinstance(value, bool):
        raise ValueError("invalid amount")
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError("amount must be finite")
        sign, digits, exp = value.as_tuple()
        if sign:
            raise ValueError("amount must be positive")
        n = int("".join(map(str, digits)) or "0")
        if n == 0:
            raise ValueError("amount must be positive")
        if exp >= 0:
            if exp > 9 or len(digits) + exp > 12:
                raise ValueError("amount too large")
            cents = n * 10 ** (exp + 2)
        elif -exp - 2 <= 0:
            cents = n * 10 ** (exp + 2)
        else:
            shift = -exp - 2
            if shift > len(digits):
                raise ValueError("amount not representable in cents")
            cents, rem = divmod(n, 10 ** shift)
            if rem:
                raise ValueError("amount not representable in cents")
    elif isinstance(value, int):
        if value <= 0 or value > MAX_CENTS // 100:
            raise ValueError("amount out of range")
        cents = value * 100
    elif isinstance(value, str):
        m = _STR_RE.fullmatch(value)
        if not m:
            raise ValueError("invalid amount string")
        sign, whole, frac = m.group(1), m.group(2), m.group(3) or ""
        if sign == "-":
            raise ValueError("amount must be positive")
        frac = frac.rstrip("0") if len(frac) > 2 else frac
        if len(frac) > 2:
            raise ValueError("amount not representable in cents")
        cents = int(whole) * 100 + int(frac.ljust(2, "0")) if (whole or frac) else 0
    else:
        raise ValueError("unsupported amount type")
    if cents <= 0:
        raise ValueError("amount must be positive")
    if cents > MAX_CENTS:
        raise ValueError("amount too large")
    return cents


def _from_cents(cents):
    digits = tuple(int(c) for c in str(cents))
    return Decimal((0, digits, -2))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
